const descriptions={'Content & Discovery':'Manage add-ons and plugins','Playback':official('playback_subtitle','Player, subtitles, and playback behaviour'),'Integrations':official('settings_integrations_section_subtitle'),'Layout':'Home, cards, details, streams, and navigation','Appearance':'Themes, typography and language','Account':'Account and sync status','Tracking':'Connect tracking providers and choose which one powers your Library and Continue Watching.','Switch Profile':'Choose and manage profiles.','Watch Party':'Join friends with a party code.','Advanced':'Experience, performance, diagnostics and cache.','About':'App information and acknowledgements.'};
function row(r,id){return `<button class="row" data-id="${id}" ${r.demo?`data-demo="${r.demo}"`:""} ${r.open?`data-open="${r.open}"`:''} aria-label="${esc(r.title)}${r.legacy?' — Legacy':''}">${r.icon?icon(r.icon):''}<span class="copy"><span class="title">${esc(r.title)}${r.legacy?'<span class="legacy">Legacy</span>':''}</span>${r.sub?`<span class="sub">${esc(r.sub)}</span>`:''}</span>${r.toggle!==undefined?`<span class="switch ${r.toggle?'on':''}" aria-hidden="true"></span>`:r.value?`<span class="value">${esc(r.value)}</span>`:''}${r.toggle===undefined?'<span class="chevron">›</span>':''}</button>`}
function subtitles(){return [R('Subtitle language','Preferred language for subtitles','English',{choices:['English','None']}),R('Secondary subtitle language','Fallback subtitle language','None'),R('Subtitle style','Text, background, outline and rendering',''),R('Second subtitle style','Independent appearance for the simultaneous second subtitle track','',{legacy:true}),R('Second subtitle delay','Synchronise the second subtitle track','0 ms',{legacy:true})];}
function connected(){return [R('Resolve playable links',official('debrid_enable_playback_description','Use a connected provider to resolve playable links.'),'',{toggle:false}),R('Resolve with',official('debrid_resolve_with_description'),'TorBox',{choices:['TorBox · example configured provider']}),R('TorBox','Connection settings for this provider','Configured · example',{icon:'cloud'}),R('Real-Debrid','Connection settings for this provider','Not configured',{icon:'cloud'}),R('Premiumize','Connection settings for this provider','Not configured',{icon:'cloud'}),R('AllDebrid key','Additional Native provider integration','Not configured',{legacy:true}),R('Switch provider on failure','Fallback provider order and attempt limits','Off',{legacy:true})];}
function render(){
 const amoled=categories[category][0]==='Appearance'&&appearancePreview.amoled;document.querySelector('.screen').classList.toggle('amoled',amoled);document.querySelector('.screen').classList.toggle('pure',amoled&&appearancePreview.surfaces);
 document.querySelector('#rail').innerHTML=categories.map(([name,ic,group],i)=>`${i&&categories[i-1][2]!==group?'<hr>':''}<button data-category="${i}" class="${i===category?'active':''}" aria-current="${i===category?'page':'false'}">${icon(ic)}<span>${esc(name)}</span></button>`).join('');
 const title=categories[category][0];document.querySelector('#heading').textContent=scene==='connected'?'Connected Services':scene==='addons'?'Add-ons':title;document.querySelector('#description').textContent=scene==='connected'?'Manage connected accounts and playable-link resolution.':scene==='addons'?'Manage installed add-ons, catalogues and additional Native sources.':descriptions[title];
 const crumb=document.querySelector('#breadcrumb');crumb.style.display=['connected','addons'].includes(scene)?'block':'none';crumb.textContent=scene==='addons'?'‹  Content & Discovery':'‹  Integrations';crumb.onclick=()=>go(scene==='addons'?'content':'integrations');
 let html='';if(scene==='connected')html=connected().map((r,i)=>row(r,'connected-'+i)).join('');
 else if(scene==='addons')html=[R('Installed add-ons','Manage existing add-ons and catalogue sources','',{icon:'addon'}),R('Catalogue order & collections','Choose and organise content rows','',{icon:'grid'}),R('Live TV & EPG','Additional Native sources: Xtream, Stalker, M3U and XMLTV','',{icon:'tv',legacy:true}),R('Switch add-on on failure','Additional fallback order and attempt limits','',{icon:'sync',legacy:true})].map((r,i)=>row(r,'addon-'+i)).join('');
 else if(title==='Playback'){for(const [name,key,ic]of parts){const id=name.toLowerCase().replaceAll(' ','-').replaceAll('&','and');const sub=key?official('playback_section_'+key+'_desc'):name==='Audio'?official('playback_section_audio_only_desc'):name==='Video'?official('playback_section_video_desc'):'Torrent engine and cache settings.';html+=row(R(name,sub,expanded.has(id)?'Open':'Closed',{icon:ic}),id);if(expanded.has(id)){html+='<div class="nested">'+(name==='Subtitles'?subtitles():[R(name+' preferences','Original settings remain grouped in this section.','Preview')]).map((r,i)=>row(r,id+'-setting-'+i)).join('')+'</div>';}}}
 else html=(pages[title]||[]).filter(r=>r.demo!=='surfaces'||appearancePreview.amoled).map((r,i)=>row(r.demo?{...r,toggle:appearancePreview[r.demo]}:r,'setting-'+i)).join('');
 const panel=document.querySelector('#panel');panel.innerHTML=html;panel.scrollTop=0;
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=Number(b.dataset.category);scene='category';expanded.clear();render();});
 document.querySelectorAll('.row').forEach(b=>b.onclick=()=>{if(b.dataset.open)return go(b.dataset.open);if(b.dataset.demo){appearancePreview[b.dataset.demo]=!appearancePreview[b.dataset.demo];render();return;}const id=b.dataset.id;if(title==='Playback'&&!id.includes('-setting-')){expanded.has(id)?expanded.delete(id):expanded.add(id);render();return;}lastRow=b;document.querySelectorAll('.row').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');document.querySelector('#dialog-title').textContent=b.querySelector('.title').childNodes[0].textContent;document.querySelector('#dialog-choices').innerHTML='';document.querySelector('#dialog').showModal();document.querySelector('#close').focus();});
 requestAnimationFrame(()=>{const rail=document.querySelector('#rail'),selected=rail.querySelector('.active');rail.scrollTop=Math.max(0,selected.offsetTop-rail.offsetTop-rail.clientHeight+selected.clientHeight+24);if(scene==='layout'){const target=panel.querySelector('[data-id="setting-4"]');panel.scrollTop=target.getBoundingClientRect().top-panel.getBoundingClientRect().top+panel.scrollTop-24;}if(scene==='subtitles'){const target=document.querySelector('[data-id="subtitles"]');panel.scrollTop=target.getBoundingClientRect().top-panel.getBoundingClientRect().top+panel.scrollTop-24;target.classList.add('chosen');}else{const target=panel.querySelector('.row');target?.classList.add('chosen');}});
}
function go(next){scene=next;expanded.clear();category=({appearance:3,layout:4,content:5,addons:5,playback:6,subtitles:6,integrations:7,connected:7,advanced:9})[next]??7;if(next==='subtitles')expanded.add('subtitles');render();}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>go(b.dataset.scene));document.querySelector('#close').onclick=()=>{document.querySelector('#dialog').close();lastRow?.focus();};
document.addEventListener('keydown',e=>{if(document.querySelector('dialog').open)return;if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Escape'].includes(e.key))return;e.preventDefault();const rail=document.querySelector('#rail'),panel=document.querySelector('#panel'),isRail=rail.contains(document.activeElement);if(e.key==='Escape'||e.key==='ArrowLeft'){if(scene==='connected')go('integrations');else if(scene==='addons')go('content');rail.querySelector('.active').focus();return;}if(e.key==='ArrowRight'){panel.querySelector('.row')?.focus();return;}const list=[...(isRail?rail.querySelectorAll('button'):panel.querySelectorAll('.row'))],i=list.indexOf(document.activeElement),step=e.key==='ArrowDown'?1:-1;const target=list[Math.max(0,Math.min(list.length-1,i+step))];target?.focus();target?.scrollIntoView({block:'nearest'});if(isRail&&target){category=Number(target.dataset.category);scene='category';render();rail.querySelector('.active').focus();}});
const params=new URLSearchParams(location.search);if(params.has('capture'))document.body.classList.add('capture');function fit(){if(!document.body.classList.contains('capture'))document.querySelector('.screen').style.transform=`translateX(-50%) scale(${Math.min(innerWidth/1920,1)})`;}window.addEventListener('resize',fit);fit();go(params.get('scene')||'content');document.fonts.ready.then(()=>go(params.get('scene')||'content'));window.previewState=()=>({scene,category:categories[category][0],size:[1920,1080],network:false});
